/**
 * Noise filter (PRE-02) and file classification helpers shared by filter, score and pack.
 * Everything here is pure path/text logic — no I/O.
 */
import type { PreprocessOptions } from '../core/contracts';
import { matchesAny, normalizePath } from './glob';

/** Lock files: generated by package managers, never reviewed by humans. */
export const LOCK_FILES = [
  'package-lock.json',
  'npm-shrinkwrap.json',
  'yarn.lock',
  'pnpm-lock.yaml',
  'bun.lock',
  'bun.lockb',
  'deno.lock',
  'poetry.lock',
  'Pipfile.lock',
  'uv.lock',
  'pdm.lock',
  'Cargo.lock',
  'go.sum',
  'Gemfile.lock',
  'composer.lock',
  'mix.lock',
  'Podfile.lock',
  'pubspec.lock',
  'packages.lock.json',
  'flake.lock',
  'gradle.lockfile',
  'Package.resolved',
] as const;

/** Extensions that are binary (reason `binary`). Lower-case, without the dot. */
// biome-ignore format: keep the extension table compact
export const BINARY_EXTENSIONS = [
  // images
  'png', 'jpg', 'jpeg', 'gif', 'bmp', 'ico', 'icns', 'webp', 'avif', 'tif', 'tiff', 'psd', 'heic', 'heif',
  // fonts
  'woff', 'woff2', 'ttf', 'otf', 'eot',
  // archives / packages
  'zip', 'tar', 'gz', 'tgz', 'bz2', 'xz', 'zst', '7z', 'rar', 'jar', 'war', 'ear', 'whl', 'gem', 'nupkg',
  // documents
  'pdf', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx', 'odt', 'ods', 'odp',
  // audio / video
  'mp3', 'mp4', 'm4a', 'mov', 'avi', 'mkv', 'webm', 'wav', 'flac', 'ogg', 'aac',
  // compiled / native / data
  'exe', 'dll', 'so', 'dylib', 'a', 'o', 'obj', 'lib', 'bin', 'dat', 'class', 'pyc', 'pyo', 'wasm', 'node',
  'sqlite', 'sqlite3', 'db',
] as const;

/**
 * Built-in noise globs (reason `noise`), see SPEC PRE-02. Directory rules match at any depth so
 * monorepo packages (`packages/x/dist/`) are covered. Rescue false positives with `filters.include`.
 */
export const NOISE_GLOBS = [
  // build output
  '**/dist/**',
  '**/build/**',
  '**/.next/**',
  '**/.nuxt/**',
  '**/.svelte-kit/**',
  '**/coverage/**',
  '**/__pycache__/**',
  '**/*.min.*',
  '**/*.map',
  // vendored code
  '**/vendor/**',
  '**/node_modules/**',
  '**/bower_components/**',
  '**/.yarn/**',
  // snapshots
  '**/__snapshots__/**',
  '**/*.snap',
  // text media and OS litter
  '**/*.svg',
  '**/.DS_Store',
] as const;

/** Markers of generated files, searched in the first {@link GENERATED_HEADER_LINES} lines. */
export const GENERATED_MARKER = /@generated\b|DO NOT EDIT/;
export const GENERATED_HEADER_LINES = 10;

const LOCK_SET = new Set<string>(LOCK_FILES);
const BINARY_SET = new Set<string>(BINARY_EXTENSIONS);

export type NoiseVerdict = { reason: 'noise' | 'binary'; rule: string } | null;

export function basename(path: string): string {
  const p = normalizePath(path);
  const i = p.lastIndexOf('/');
  return i < 0 ? p : p.slice(i + 1);
}

export function dirname(path: string): string {
  const p = normalizePath(path);
  const i = p.lastIndexOf('/');
  return i < 0 ? '' : p.slice(0, i);
}

/** Lower-case extension without the dot (`''` when none; dotfiles like `.env` have none). */
export function extension(path: string): string {
  const base = basename(path);
  const i = base.lastIndexOf('.');
  return i <= 0 ? '' : base.slice(i + 1).toLowerCase();
}

export function isBinaryPath(path: string): boolean {
  return BINARY_SET.has(extension(path));
}

/** Built-in rules only (no include/exclude). */
export function builtinNoise(path: string): NoiseVerdict {
  const base = basename(path);
  if (LOCK_SET.has(base)) return { reason: 'noise', rule: 'lockfile' };
  if (isBinaryPath(path)) return { reason: 'binary', rule: 'binary' };
  for (const g of NOISE_GLOBS) {
    if (matchesAny(path, [g])) return { reason: 'noise', rule: g };
  }
  return null;
}

/**
 * Path-level noise decision. Precedence: user `exclude` > user `include` > built-in list.
 * `include` only rescues files from the built-in list; it never overrides an explicit exclude.
 */
export function classifyPath(
  path: string,
  options: Pick<PreprocessOptions, 'include' | 'exclude'>,
): NoiseVerdict {
  if (options.exclude.length > 0 && matchesAny(path, options.exclude))
    return { reason: 'noise', rule: 'exclude' };
  if (options.include.length > 0 && matchesAny(path, options.include)) return null;
  return builtinNoise(path);
}

/** True when the path is rescued by `include` (generated-header detection is skipped too). */
export function isIncluded(path: string, options: Pick<PreprocessOptions, 'include'>): boolean {
  return options.include.length > 0 && matchesAny(path, options.include);
}

/** True when any of the first lines carries a generated-code marker. */
export function hasGeneratedHeader(lines: readonly string[]): boolean {
  const n = Math.min(lines.length, GENERATED_HEADER_LINES);
  for (let i = 0; i < n; i++) {
    if (GENERATED_MARKER.test(lines[i] as string)) return true;
  }
  return false;
}

/** First `n` lines of `text` without splitting the whole (possibly 1MB) string. */
export function firstLines(text: string, n: number): string[] {
  const out: string[] = [];
  let start = 0;
  while (out.length < n && start <= text.length) {
    const nl = text.indexOf('\n', start);
    if (nl < 0) {
      out.push(text.slice(start));
      break;
    }
    out.push(text.slice(start, nl));
    start = nl + 1;
  }
  return out;
}

// ─────────────────────────── test / config classification (PRE-07) ───────────────────────────

export const TEST_GLOBS = [
  '**/{test,tests,__tests__,spec,specs,e2e,__mocks__,testdata,fixtures}/**',
  '**/*.{test,spec}.*',
  '**/*_test.go',
  '**/test_*.py',
  '**/*_test.py',
  '**/*{Test,Tests}.{java,kt}',
] as const;

export const CONFIG_GLOBS = [
  '**/*.config.{js,cjs,mjs,ts,cts,mts,json}',
  '**/.*rc',
  '**/.*rc.{js,cjs,mjs,json,yml,yaml}',
  '**/tsconfig*.json',
  '**/{Dockerfile,Makefile,Procfile,Jenkinsfile}',
  '**/*.Dockerfile',
  '**/docker-compose*.{yml,yaml}',
  '.github/**',
  '**/*.{json,yml,yaml,toml,ini,cfg,properties,conf}',
  '**/.env*',
  '**/.{editorconfig,gitignore,gitattributes,npmrc,nvmrc,dockerignore}',
] as const;

export function isTestPath(path: string): boolean {
  return matchesAny(path, TEST_GLOBS);
}

export function isConfigPath(path: string): boolean {
  return matchesAny(path, CONFIG_GLOBS);
}
